package org.schabi.newpipe

import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Test
import org.junit.runner.RunWith
import org.schabi.newpipe.settings.SettingsActivity

@RunWith(AndroidJUnit4::class)
class NotificationSettingsCrashTest {

    @Test
    fun reproduceNotificationSettingsCrash() {
        val context = ApplicationProvider.getApplicationContext<android.content.Context>()
        val prefs = context.getSharedPreferences("org.schabi.newpipe_preferences", android.content.Context.MODE_PRIVATE)

        // Toggle notification setting directly to trigger foreground service
        val currentValue = prefs.getBoolean("enable_notifications", false)
        prefs.edit().putBoolean("enable_notifications", !currentValue).commit()

        // Force foreground service initialization
        InstrumentationRegistry.getInstrumentation().runOnMainSync {
            SettingsActivity.initNotificationSettings(context)
        }
    }
}

